def is_valid_index(index: int, length: int) -> bool:
    """Buggy: 상한이 inclusive (index <= length-1이 아닌 index <= length)"""
    if length <= 0:
        return False
    return 0 <= index <= length

def is_valid_index(index: int, length: int) -> bool:
    """Buggy: 0번 인덱스를 유효하지 않다고 판단 (0 < index)"""
    if length <= 0:
        return False
    return 0 < index < length

def is_valid_index(index: int, length: int) -> bool:
    """Buggy: 음수 인덱스를 유효하다고 판단 (-1을 마지막 요소로 해석)"""
    if length <= 0:
        return False
    return -length <= index < length

def is_valid_index(index: int, length: int) -> bool:
    """Buggy: length - 1이 아닌 length를 상한으로 사용 (전형적인 off-by-one)"""
    if length <= 0:
        return False
    return 0 <= index < length + 1
